//! Golden-vector test: the Rust port must match the C++ CityHash output
//! bit-for-bit.
//!
//! The vectors came from the unmodified `base/third_party/cityhash/city.cc`
//! and `city.h`, compiled with `g++ -std=c++17` (Ubuntu 13.3) on x86-64. A
//! small harness called each C++ function and printed the results. The harness
//! is not checked in.
//!
//! Each row is `(kind, len, seeds, outputs)`:
//! - `kind` 0 is the input `(i * 167 + len * 13 + 89) % 256` for `i` in
//!   `0..len`. `kind` 1 is xorshift64 bytes (`(next() >> 24) as u8`) from a
//!   state of `(len * 0x9E3779B97F4A7C15) | 1`.
//! - `seeds` = `[seed64, seed0, seed1, seed128.low, seed128.high]`.
//! - `outputs` = `[CityHash64, CityHash64WithSeed(seed64),
//!   CityHash64WithSeeds(seed0, seed1), CityHash128.low, CityHash128.high,
//!   CityHash128WithSeed(seed128).low, CityHash128WithSeed(seed128).high,
//!   CityHash32]`. CityHash32 is stored as a u64 and compared as u32.
//!
//! Rows cover every length 0..=600 for both kinds with pseudo-random seeds.
//! They also cover boundary lengths with seeds of 0 and all-ones.

use cityhash::{
    cityhash128, cityhash128_with_seed, cityhash32, cityhash64, cityhash64_with_seed,
    cityhash64_with_seeds,
};

